function ProductCard({ name, price }) {
  return (
    <div className="card">
      <h3>{name}</h3>
      <p>R{price}</p>
    </div>
  );
}

function App() {
  return <ProductCard name="Calculator" price={4500} />;
}

import { useState } from 'react';

function Counter() {
  const [count, setCount] = useState(0);
  return (
    <button onClick={() => setCount(c => c + 1)}>
      Clicked {count} times
    </button>
  );
}

function ProductList({ products }) {
  const cheap = products.filter(p => p.price < 1000);
  if (cheap.length === 0) return <p>No items under R1000.</p>;
  return (
    <ul>
      {cheap.map(p => <li key={p.id}>{p.name}: R{p.price}</li>)}
    </ul>
  );
}

function Courses() {
  const [courses, setCourses] = useState([]);
  const [error, setError] = useState(null);
  useEffect(() => {
    fetch('/api/courses')
      .then(r => { if (!r.ok) throw new Error('Request failed'); return r.json(); })
      .then(setCourses)
      .catch(e => setError(e.message));
  }, []);
  if (error) return <p>Could not load courses: {error}</p>;
  return <ul>{courses.map(c => <li key={c.id}>{c.title}</li>)}</ul>;
}
